// [seamvk] Native Vulkan renderer: see include/runtime/ps2_seamvk.h and seamvk/seamgs_internal.h.
// Built only with the paraLLEl-GS backend (it shares its Granite device). The GLSL lives in
// src/lib/seamvk/; the .inc files are their SPIR-V (glslc -mfmt=num), regenerated by hand.
//
// Render targets: one RGBA8 image per FRAME base (fbp), one D32 image per ZBUF base, all at a
// fixed logical 1024x512 GS pixels times PS2X_SEAMVK_SCALE. Draws run in stream order, switching
// render passes when the target pair changes. Targets hold exact GS bytes (alpha included); the
// As/128 blend factors come from a dual-source fragment output.
// At the swap the CRTC circuits (DISPFB/DISPLAY) are composed into a 640x448*scale frame,
// read back and handed to the present thread.
#include "runtime/ps2_seamvk.h"
#include "runtime/ps2_gs_gpu_renderer.h"   // [dofoff] GsGpuRenderer::dofBlurEnabled
#include "runtime/ps2x_memstat.h"   // [loglevel] ps2xLogLevel
#include "runtime/ps2_gs_pgs.h"   // [targetdump] the backend's view of a target
#include "runtime/ps2_wshud.h"   // [wshud]
#include "seamvk/seamgs_internal.h"

#include "device.hpp"
#include "context.hpp"     // [standalone] the seam's own Vulkan context/device
#include "thread_id.hpp"   // [standalone] Util::register_thread_index
#include "runtime/ps2_memory.h"   // [standalone] GSRegisters (the live privileged-register block)
#include "command_buffer.hpp"
#include "image.hpp"
#include "buffer.hpp"
#include "sampler.hpp"

#include <algorithm>
#include <filesystem>
#include <deque>
#include <thread>
#include <condition_variable>
#include <unordered_set>
#include <unordered_map>
#include <atomic>
extern std::atomic<uint64_t> g_bt3FrameCount;   // game_overrides.cpp: the game's frame counter
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <map>
#include <mutex>
